# PressRelease: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Pressrelease:
    release_id: str = None  # ID
    headline: str = None  # Headline
    issued_at: str = None  # ISO 8601
    contact: str = None  # Contact
    embargo: str = None  # Embargo or null

REQUIRED = ["release_id", "headline", "issued_at", "contact"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'release_id': 'PR-2201', 'headline': 'Acme Launches Widget 2.0', 'issued_at': '2026-06-15T09:00:00Z', 'contact': 'press@acme.example', 'embargo': None}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

